{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket lacks an aws_s3_bucket_public_access_block resource, leaving it potentially exposed to public access if other configurations allow it."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have server-side encryption configured. CloudTrail logs contain sensitive audit data and should be encrypted at rest using SSE-KMS or SSE-S3."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "Versioning is not enabled on the S3 bucket. For CloudTrail logs, versioning helps protect against accidental deletion or overwriting of log files."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "Server access logging is not enabled for the S3 bucket. This prevents tracking of requests made to the bucket, which is critical for security auditing."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = "smart-city-parking-management-system-s3-cloudtrail-${random_string.cloudtrail_suffix.result}"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  target_bucket = aws_s3_bucket.cloudtrail_logs.id # In production, this should point to a separate dedicated logging bucket
  target_prefix = "log/"
}",
  "fix_summary": "Added aws_s3_bucket_public_access_block to prevent public exposure, aws_s3_bucket_server_side_encryption_configuration to enforce KMS encryption, aws_s3_bucket_versioning to enable versioning, and aws_s3_bucket_logging to enable access logging. Note: The logging configuration currently points to itself for simplicity; in a production environment, this should reference a separate, dedicated logging bucket."
}
